export const EMBEDDED_MIGRATIONS: [name: string, sql: string][] = [
  ["001_core.sql", "-- 001_core: organisation, users, roles, sessions, audit log, numbering, idempotency.\n-- Runs as the owner role. The application connects as akb_app (see 000_roles in db/README.md).\n\ncreate extension if not exists pgcrypto;\ncreate extension if not exists citext;\n\n-- ---------------------------------------------------------------------------\n-- Organisation\n-- ---------------------------------------------------------------------------\ncreate table firms (\n  id          serial primary key,\n  code        text not null unique,\n  name        text not null,\n  legal_name  text,\n  created_at  timestamptz not null default now()\n);\n\ncreate table branches (\n  id        serial primary key,\n  firm_id   int not null references firms(id),\n  code      text not null unique,\n  name_en   text not null,\n  name_ur   text,\n  kind      text not null default 'godown' check (kind in ('godown','office','sale_point')),\n  owned     boolean,\n  active    boolean not null default true\n);\n\n-- Business vs personal vs rental separation on every ledger line.\ncreate table cost_centres (\n  id    serial primary key,\n  code  text not null unique,\n  name  text not null\n);\n\n-- ---------------------------------------------------------------------------\n-- Roles and permissions\n-- ---------------------------------------------------------------------------\ncreate table roles (\n  code        text primary key,\n  name        text not null,\n  description text\n);\n\ncreate table permissions (\n  code        text primary key,\n  description text not null\n);\n\ncreate table role_permissions (\n  role_code       text not null references roles(code),\n  permission_code text not null references permissions(code),\n  primary key (role_code, permission_code)\n);\n\ncreate table users (\n  id              serial primary key,\n  username        citext not null unique,\n  full_name       text not null,\n  role_code       text not null references roles(code),\n  branch_ids      int[],              -- null = all branches\n  active          boolean not null default true,\n  password_hash   text not null,\n  totp_secret     text,\n  totp_enabled    boolean not null default false,\n  failed_logins   int not null default 0,\n  locked_until    timestamptz,\n  must_change_pw  boolean not null default true,\n  created_at      timestamptz not null default now(),\n  created_by      int references users(id)\n);\n\ncreate table sessions (\n  id            uuid primary key default gen_random_uuid(),\n  user_id       int not null references users(id),\n  token_hash    text not null unique,     -- sha256 of the bearer token; the token itself is never stored\n  scope         text not null default 'full' check (scope in ('full','limited')),  -- limited: must change password / set up 2FA first\n  created_at    timestamptz not null default now(),\n  last_seen_at  timestamptz not null default now(),\n  expires_at    timestamptz not null,\n  revoked_at    timestamptz,\n  ip            text,\n  user_agent    text\n);\ncreate index sessions_user_idx on sessions(user_id);\n\n-- ---------------------------------------------------------------------------\n-- Audit log: append-only, each row hashed with the previous row's hash.\n-- Timestamps are hashed as microseconds since 1970 so the hash does not depend on the session time zone.\n-- ---------------------------------------------------------------------------\ncreate table audit_log (\n  id         bigserial primary key,\n  at         timestamptz not null default clock_timestamp(),\n  user_id    int references users(id),\n  action     text not null,\n  entity     text not null,\n  entity_id  text,\n  detail     jsonb,\n  prev_hash  text,\n  hash       text not null\n);\ncreate index audit_entity_idx on audit_log(entity, entity_id);\n\ncreate or replace function audit_log_chain() returns trigger language plpgsql as $$\ndeclare\n  last_hash text;\nbegin\n  -- Serialise writers so the chain has no forks.\n  perform pg_advisory_xact_lock(724001);\n  select hash into last_hash from audit_log order by id desc limit 1;\n  new.prev_hash := last_hash;\n  new.hash := encode(digest(\n      coalesce(last_hash, '') || '|' || (extract(epoch from new.at) * 1000000)::bigint::text || '|' || coalesce(new.user_id::text, '') || '|' ||\n      new.action || '|' || new.entity || '|' || coalesce(new.entity_id, '') || '|' || coalesce(new.detail::text, ''),\n      'sha256'), 'hex');\n  return new;\nend $$;\n\ncreate trigger audit_log_chain before insert on audit_log\n  for each row execute function audit_log_chain();\n\ncreate or replace function forbid_change() returns trigger language plpgsql as $$\nbegin\n  raise exception '% is append-only: % is not allowed', tg_table_name, tg_op\n    using errcode = 'P0001';\nend $$;\n\ncreate trigger audit_log_no_update before update or delete on audit_log\n  for each row execute function forbid_change();\n\n-- Recompute the chain and return the first broken row id, or null if intact.\ncreate or replace function audit_log_verify() returns bigint language plpgsql as $$\ndeclare\n  r record;\n  expected text;\n  last_hash text := null;\nbegin\n  for r in select * from audit_log order by id loop\n    expected := encode(digest(\n      coalesce(last_hash, '') || '|' || (extract(epoch from r.at) * 1000000)::bigint::text || '|' || coalesce(r.user_id::text, '') || '|' ||\n      r.action || '|' || r.entity || '|' || coalesce(r.entity_id, '') || '|' || coalesce(r.detail::text, ''),\n      'sha256'), 'hex');\n    if r.hash <> expected or r.prev_hash is distinct from last_hash then\n      return r.id;\n    end if;\n    last_hash := r.hash;\n  end loop;\n  return null;\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- Gapless document numbers (sequences skip numbers on rollback; this does not).\n-- Fiscal year in Pakistan runs July to June: FY 2026-27 is labelled 2627.\n-- ---------------------------------------------------------------------------\ncreate table doc_counters (\n  doc_type  text not null,\n  fy_label  text not null,\n  next_no   int  not null default 1,\n  primary key (doc_type, fy_label)\n);\n\ncreate or replace function fy_label(d date) returns text language sql immutable as $$\n  select case when extract(month from d) >= 7\n    then lpad((extract(year from d)::int % 100)::text, 2, '0') || lpad(((extract(year from d)::int + 1) % 100)::text, 2, '0')\n    else lpad(((extract(year from d)::int - 1) % 100)::text, 2, '0') || lpad((extract(year from d)::int % 100)::text, 2, '0')\n  end\n$$;\n\ncreate or replace function next_doc_no(p_doc_type text, p_date date) returns text language plpgsql as $$\ndeclare\n  fy text := fy_label(p_date);\n  n int;\nbegin\n  insert into doc_counters(doc_type, fy_label) values (p_doc_type, fy)\n    on conflict do nothing;\n  update doc_counters set next_no = next_no + 1\n    where doc_type = p_doc_type and fy_label = fy\n    returning next_no - 1 into n;\n  return p_doc_type || '-' || fy || '-' || lpad(n::text, 5, '0');\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- Idempotency: a retried request with the same key returns the first response.\n-- ---------------------------------------------------------------------------\ncreate table idempotency_keys (\n  key          text not null,\n  user_id      int  not null references users(id),\n  route        text not null,\n  status_code  int  not null,\n  response     jsonb not null,\n  created_at   timestamptz not null default now(),\n  primary key (key, user_id)\n);\n\n-- Session context helpers used by row-level security.\ncreate or replace function app_user_id() returns int language sql stable as $$\n  select nullif(current_setting('app.user_id', true), '')::int\n$$;\ncreate or replace function app_role() returns text language sql stable as $$\n  select nullif(current_setting('app.role', true), '')\n$$;\n"],
  ["002_masters.sql", "-- 002_masters: parties and products.\n\ncreate table parties (\n  id            serial primary key,\n  code          text not null unique,\n  kind          text not null check (kind in ('customer','supplier','transporter','tenant','employee','other')),\n  name_en       text not null,\n  name_ur       text,\n  city          text,\n  phone         text,\n  tax_no        text,\n  filer         boolean,\n  credit_limit  numeric(18,2) not null default 0 check (credit_limit >= 0),\n  credit_days   int not null default 30 check (credit_days >= 0),\n  rep_user_id   int references users(id),   -- sales rep who owns this customer\n  active        boolean not null default true,\n  created_at    timestamptz not null default now(),\n  created_by    int references users(id)\n);\ncreate index parties_kind_idx on parties(kind);\ncreate index parties_rep_idx on parties(rep_user_id);\ncreate index parties_name_trgm on parties (lower(name_en));\n\ncreate table products (\n  id            serial primary key,\n  code          text not null unique,\n  name_en       text not null,\n  name_ur       text,\n  manufacturer  text not null,\n  nutrient      text,                      -- urea, DAP, NP, CAN, SSP, SOP, MOP, AS\n  bag_kg        numeric(6,2) not null default 50 check (bag_kg > 0),\n  floor_price   numeric(18,2) check (floor_price is null or floor_price > 0),\n  active        boolean not null default true\n);\n"],
  ["003_ledger.sql", "-- 003_ledger: chart of accounts, double-entry journal, day locks.\n-- Rules enforced here, not only in the API:\n--   * every posted entry balances (debits = credits, at least two lines)\n--   * posted entries and their lines can never be updated or deleted; corrections are reversals\n--   * nothing can be posted into a locked business day\n--   * receivable/payable lines must name a party\n--   * posted entries get a gapless number per fiscal year\n\ncreate table accounts (\n  id           serial primary key,\n  code         text not null unique,\n  name         text not null,\n  type         text not null check (type in ('asset','liability','equity','income','expense')),\n  parent_id    int references accounts(id),\n  postable     boolean not null default true,\n  control      text check (control in ('receivable','payable','bank','cash')),\n  active       boolean not null default true,\n  created_at   timestamptz not null default now()\n);\n\ncreate table bank_accounts (\n  id            serial primary key,\n  account_id    int not null unique references accounts(id),\n  bank_name     text not null,\n  branch_name   text,\n  account_title text,\n  account_no    text,\n  active        boolean not null default true\n);\n\ncreate table business_days (\n  business_date  date primary key,\n  status         text not null default 'open' check (status in ('open','locked')),\n  locked_at      timestamptz,\n  locked_by      int references users(id),\n  checklist      jsonb,\n  export_sha256  text,           -- checksum of the stored Excel day book\n  export_xlsx    bytea,          -- the day book exactly as generated at lock time\n  export_csv     text,\n  csv_sha256     text\n);\n\ncreate table journal_entries (\n  id            bigserial primary key,\n  entry_no      text unique,\n  firm_id       int not null references firms(id),\n  business_date date not null,\n  narration     text not null,\n  source_type   text not null,       -- manual, dispatch, receipt, cheque_return, reversal, opening, import ...\n  source_id     text,\n  status        text not null default 'posted' check (status in ('draft','pending_approval','posted')),\n  reversal_of   bigint unique references journal_entries(id),\n  reversed_by   bigint references journal_entries(id),\n  created_by    int not null references users(id),\n  created_at    timestamptz not null default now(),\n  approved_by   int references users(id),\n  approved_at   timestamptz,\n  posted_at     timestamptz,\n  posted_txid   bigint\n);\ncreate index je_date_idx on journal_entries(business_date);\ncreate index je_source_idx on journal_entries(source_type, source_id);\n\ncreate table journal_lines (\n  id              bigserial primary key,\n  entry_id        bigint not null references journal_entries(id),\n  line_no         int not null,\n  account_id      int not null references accounts(id),\n  party_id        int references parties(id),\n  branch_id       int references branches(id),\n  cost_centre_id  int references cost_centres(id),\n  debit           numeric(18,2) not null default 0 check (debit >= 0),\n  credit          numeric(18,2) not null default 0 check (credit >= 0),\n  memo            text,\n  check ((debit > 0 and credit = 0) or (credit > 0 and debit = 0)),\n  unique (entry_id, line_no)\n);\ncreate index jl_account_idx on journal_lines(account_id);\ncreate index jl_party_idx on journal_lines(party_id);\n\n-- ---------------------------------------------------------------------------\ncreate or replace function assert_day_open(d date) returns void language plpgsql as $$\nbegin\n  if exists (select 1 from business_days where business_date = d and status = 'locked') then\n    raise exception 'Business date % is locked; post the correction on an open day', d\n      using errcode = 'P0001';\n  end if;\nend $$;\n\ncreate or replace function je_before_insert() returns trigger language plpgsql as $$\nbegin\n  if new.reversed_by is not null then\n    raise exception 'A new entry cannot already be reversed' using errcode = 'P0001';\n  end if;\n  if new.status = 'posted' then\n    perform assert_day_open(new.business_date);\n    new.posted_at := now();\n    new.posted_txid := txid_current();\n    new.entry_no := next_doc_no('JV', new.business_date);\n  else\n    new.entry_no := null;\n    new.posted_at := null;\n    new.posted_txid := null;\n  end if;\n  return new;\nend $$;\ncreate trigger je_before_insert before insert on journal_entries\n  for each row execute function je_before_insert();\n\ncreate or replace function je_before_update() returns trigger language plpgsql as $$\nbegin\n  if old.status = 'posted' then\n    -- The only change allowed on a posted entry is recording its reversal, once.\n    if old.reversed_by is null and new.reversed_by is not null\n       and (to_jsonb(new) - 'reversed_by') = (to_jsonb(old) - 'reversed_by') then\n      return new;\n    end if;\n    raise exception 'Posted journal entry % cannot be changed; reverse it instead', old.entry_no\n      using errcode = 'P0001';\n  end if;\n  if new.status = 'posted' then\n    -- Maker-checker: an entry that waited for approval cannot be approved by its creator.\n    if old.status = 'pending_approval' and new.approved_by is not distinct from old.created_by then\n      raise exception 'The person who created an entry cannot approve it' using errcode = 'P0001';\n    end if;\n    perform assert_day_open(new.business_date);\n    new.posted_at := now();\n    new.posted_txid := txid_current();\n    new.entry_no := next_doc_no('JV', new.business_date);\n  end if;\n  return new;\nend $$;\ncreate trigger je_before_update before update on journal_entries\n  for each row execute function je_before_update();\n\ncreate or replace function je_before_delete() returns trigger language plpgsql as $$\nbegin\n  if old.status = 'posted' then\n    raise exception 'Posted journal entry % cannot be deleted; reverse it instead', old.entry_no\n      using errcode = 'P0001';\n  end if;\n  return old;\nend $$;\ncreate trigger je_before_delete before delete on journal_entries\n  for each row execute function je_before_delete();\n\ncreate or replace function jl_guard() returns trigger language plpgsql as $$\ndeclare\n  e record;\n  a record;\nbegin\n  select status, posted_txid into e from journal_entries\n    where id = coalesce(new.entry_id, old.entry_id);\n  if tg_op in ('UPDATE','DELETE') then\n    if e.status = 'posted' then\n      raise exception 'Lines of a posted entry cannot be changed' using errcode = 'P0001';\n    end if;\n    if tg_op = 'DELETE' then return old; end if;\n  end if;\n  if tg_op = 'INSERT' and e.status = 'posted' and e.posted_txid is distinct from txid_current() then\n    raise exception 'Lines cannot be added to a posted entry' using errcode = 'P0001';\n  end if;\n  select postable, active, control into a from accounts where id = new.account_id;\n  if not a.postable or not a.active then\n    raise exception 'Account % is not open for posting', new.account_id using errcode = 'P0001';\n  end if;\n  if a.control in ('receivable','payable') and new.party_id is null then\n    raise exception 'A receivable or payable line must name a party' using errcode = 'P0001';\n  end if;\n  return new;\nend $$;\ncreate trigger jl_guard before insert or update or delete on journal_lines\n  for each row execute function jl_guard();\n\n-- Deferred to commit time, so an entry and all its lines can be written in one transaction.\ncreate or replace function je_check_balanced() returns trigger language plpgsql as $$\ndeclare\n  eid bigint;\n  st text;\n  d numeric; c numeric; n int;\nbegin\n  if tg_table_name = 'journal_lines' then eid := new.entry_id; else eid := new.id; end if;\n  select status into st from journal_entries where id = eid;\n  if st <> 'posted' then return null; end if;\n  select coalesce(sum(debit),0), coalesce(sum(credit),0), count(*) into d, c, n\n    from journal_lines where entry_id = eid;\n  if n < 2 then\n    raise exception 'Journal entry % needs at least two lines', eid using errcode = 'P0001';\n  end if;\n  if d <> c then\n    raise exception 'Journal entry % does not balance: debits % vs credits %', eid, d, c using errcode = 'P0001';\n  end if;\n  if d = 0 then\n    raise exception 'Journal entry % has no amount', eid using errcode = 'P0001';\n  end if;\n  return null;\nend $$;\n\ncreate constraint trigger je_balanced_on_entry after insert or update on journal_entries\n  deferrable initially deferred for each row execute function je_check_balanced();\ncreate constraint trigger je_balanced_on_line after insert on journal_lines\n  deferrable initially deferred for each row execute function je_check_balanced();\n\n-- Reverse a posted entry with an opposite entry, linking both. Returns the new entry id.\ncreate or replace function reverse_entry(p_entry_id bigint, p_user_id int, p_reason text, p_date date)\nreturns bigint language plpgsql as $$\ndeclare\n  o record;\n  new_id bigint;\nbegin\n  select * into o from journal_entries where id = p_entry_id for update;\n  if not found then raise exception 'Journal entry % not found', p_entry_id using errcode = 'P0002'; end if;\n  if o.status <> 'posted' then raise exception 'Only posted entries can be reversed' using errcode = 'P0001'; end if;\n  if o.reversed_by is not null then raise exception 'Entry % is already reversed', o.entry_no using errcode = 'P0001'; end if;\n  if o.reversal_of is not null then raise exception 'A reversal cannot itself be reversed; post a new entry' using errcode = 'P0001'; end if;\n  if coalesce(trim(p_reason), '') = '' then raise exception 'A reason is required' using errcode = 'P0001'; end if;\n\n  insert into journal_entries(firm_id, business_date, narration, source_type, source_id, status, reversal_of, created_by, approved_by, approved_at)\n    values (o.firm_id, p_date, 'Reversal of ' || o.entry_no || ': ' || p_reason, 'reversal', o.id::text, 'posted', o.id, p_user_id, p_user_id, now())\n    returning id into new_id;\n\n  insert into journal_lines(entry_id, line_no, account_id, party_id, branch_id, cost_centre_id, debit, credit, memo)\n    select new_id, line_no, account_id, party_id, branch_id, cost_centre_id, credit, debit, memo\n      from journal_lines where entry_id = o.id order by line_no;\n\n  update journal_entries set reversed_by = new_id where id = o.id;\n  return new_id;\nend $$;\n\n-- ---------------------------------------------------------------------------\ncreate view posted_lines as\n  select l.*, e.entry_no, e.business_date, e.narration, e.source_type, e.source_id, e.firm_id,\n         e.reversal_of, e.reversed_by\n    from journal_lines l join journal_entries e on e.id = l.entry_id\n   where e.status = 'posted';\n\ncreate view account_balances as\n  select a.id as account_id, a.code, a.name, a.type, a.control,\n         coalesce(sum(p.debit),0)  as debit,\n         coalesce(sum(p.credit),0) as credit,\n         coalesce(sum(p.debit - p.credit),0) as balance\n    from accounts a left join posted_lines p on p.account_id = a.id\n   group by a.id;\n\n-- Receivable balance per party (positive = party owes AKB; negative = advance held).\ncreate view party_receivables as\n  select p.party_id, coalesce(sum(p.debit - p.credit),0) as balance\n    from posted_lines p join accounts a on a.id = p.account_id\n   where a.control = 'receivable'\n   group by p.party_id;\n"],
  ["004_stock.sql", "-- 004_stock: stock is never typed in. It is the sum of movements, and movements are append-only.\n\ncreate table stock_movements (\n  id             bigserial primary key,\n  business_date  date not null,\n  kind           text not null check (kind in ('opening','receipt','dispatch','transfer_out','transfer_in','adjustment')),\n  product_id     int not null references products(id),\n  branch_id      int not null references branches(id),\n  bags           int not null check (bags <> 0),\n  ref_type       text not null,\n  ref_id         text not null,\n  note           text,\n  created_by     int not null references users(id),\n  created_at     timestamptz not null default now(),\n  check (\n    (kind in ('opening','receipt','transfer_in') and bags > 0) or\n    (kind in ('dispatch','transfer_out') and bags < 0) or\n    (kind = 'adjustment')\n  )\n);\ncreate index sm_product_branch_idx on stock_movements(product_id, branch_id);\ncreate index sm_ref_idx on stock_movements(ref_type, ref_id);\n\ncreate or replace function sm_before_insert() returns trigger language plpgsql as $$\ndeclare\n  on_hand bigint;\nbegin\n  perform assert_day_open(new.business_date);\n  -- Serialise movements for one product at one branch so the balance check is reliable.\n  perform pg_advisory_xact_lock(new.product_id, new.branch_id);\n  if new.bags < 0 then\n    select coalesce(sum(bags),0) into on_hand from stock_movements\n      where product_id = new.product_id and branch_id = new.branch_id;\n    if on_hand + new.bags < 0 then\n      raise exception 'Not enough stock: % bags on hand, % requested', on_hand, -new.bags\n        using errcode = 'P0001';\n    end if;\n  end if;\n  return new;\nend $$;\ncreate trigger sm_before_insert before insert on stock_movements\n  for each row execute function sm_before_insert();\ncreate trigger sm_no_change before update or delete on stock_movements\n  for each row execute function forbid_change();\n\ncreate view stock_on_hand as\n  select product_id, branch_id, sum(bags)::bigint as bags\n    from stock_movements group by product_id, branch_id;\n\n-- ---------------------------------------------------------------------------\ncreate table goods_receipts (\n  id             bigserial primary key,\n  gr_no          text not null unique,\n  business_date  date not null,\n  branch_id      int not null references branches(id),\n  supplier_id    int references parties(id),\n  company_order_ref text,          -- the company's CO number until the finance module links orders\n  truck_no       text,\n  note           text,\n  created_by     int not null references users(id),\n  created_at     timestamptz not null default now()\n);\n\ncreate table goods_receipt_lines (\n  id             bigserial primary key,\n  gr_id          bigint not null references goods_receipts(id),\n  product_id     int not null references products(id),\n  bags_received  int not null check (bags_received > 0),\n  bags_short     int not null default 0 check (bags_short >= 0),\n  bags_damaged   int not null default 0 check (bags_damaged >= 0)\n);\n\ncreate table stock_transfers (\n  id             bigserial primary key,\n  transfer_no    text not null unique,\n  business_date  date not null,\n  from_branch_id int not null references branches(id),\n  to_branch_id   int not null references branches(id),\n  truck_no       text,\n  status         text not null default 'in_transit' check (status in ('in_transit','received')),\n  created_by     int not null references users(id),\n  created_at     timestamptz not null default now(),\n  received_by    int references users(id),\n  received_at    timestamptz,\n  received_date  date,\n  check (from_branch_id <> to_branch_id)\n);\n\ncreate table stock_transfer_lines (\n  id           bigserial primary key,\n  transfer_id  bigint not null references stock_transfers(id),\n  product_id   int not null references products(id),\n  bags         int not null check (bags > 0)\n);\n\ncreate table stock_adjustments (\n  id             bigserial primary key,\n  adj_no         text not null unique,\n  business_date  date not null,\n  branch_id      int not null references branches(id),\n  product_id     int not null references products(id),\n  bags           int not null check (bags <> 0),\n  reason         text not null,\n  status         text not null default 'pending' check (status in ('pending','approved','rejected')),\n  requested_by   int not null references users(id),\n  requested_at   timestamptz not null default now(),\n  decided_by     int references users(id),\n  decided_at     timestamptz,\n  decision_note  text\n);\n"],
  ["005_sales.sql", "-- 005_sales: orders generated (OGs), dispatches, receipts and their allocation, cheque returns.\n-- Payment status is never stored: it is derived from allocations (see og_status view).\n\ncreate table ogs (\n  id                bigserial primary key,\n  og_no             text unique,                -- assigned on submit\n  business_date     date not null,\n  customer_id       int not null references parties(id),\n  branch_id         int not null references branches(id),\n  terms             text not null check (terms in ('cbd','credit','loan')),\n  advance_pct       numeric(5,2) not null default 0 check (advance_pct between 0 and 100),\n  credit_days       int not null default 0 check (credit_days >= 0),\n  freight_by        text not null default 'customer' check (freight_by in ('customer','akb')),\n  freight_per_bag   numeric(18,2) not null default 0 check (freight_per_bag >= 0),\n  discount          numeric(18,2) not null default 0 check (discount >= 0),\n  status            text not null default 'draft' check (status in ('draft','submitted','approved','rejected','cancelled')),\n  approval_reasons  text[] not null default '{}',\n  unpurchased_bags  int not null default 0 check (unpurchased_bags >= 0),\n  due_date          date,\n  note              text,\n  created_by        int not null references users(id),\n  created_at        timestamptz not null default now(),\n  submitted_at      timestamptz,\n  decided_by        int references users(id),\n  decided_at        timestamptz,\n  decision_comment  text,\n  rep_user_id       int references users(id)       -- copied from the customer for row-level security\n);\ncreate index ogs_customer_idx on ogs(customer_id);\ncreate index ogs_status_idx on ogs(status);\n\ncreate table og_lines (\n  id            bigserial primary key,\n  og_id         bigint not null references ogs(id),\n  line_no       int not null,\n  product_id    int not null references products(id),\n  bags          int not null check (bags > 0),\n  rate          numeric(18,2) not null check (rate > 0),\n  floor_price   numeric(18,2),\n  unique (og_id, line_no)\n);\n\n-- An OG's lines are fixed once it leaves draft.\ncreate or replace function og_lines_guard() returns trigger language plpgsql as $$\ndeclare st text;\nbegin\n  select status into st from ogs where id = coalesce(new.og_id, old.og_id);\n  if st <> 'draft' then\n    raise exception 'Lines of a submitted OG cannot be changed' using errcode = 'P0001';\n  end if;\n  if tg_op = 'DELETE' then return old; end if;\n  return new;\nend $$;\ncreate trigger og_lines_guard before insert or update or delete on og_lines\n  for each row execute function og_lines_guard();\n\n-- ---------------------------------------------------------------------------\ncreate table dispatches (\n  id               bigserial primary key,\n  dispatch_no      text not null unique,\n  og_id            bigint not null references ogs(id),\n  business_date    date not null,\n  branch_id        int not null references branches(id),\n  truck_no         text not null,\n  driver_name      text,\n  bilty_no         text,\n  gate_pass_no     text not null unique,\n  transporter_id   int references parties(id),\n  freight_per_bag  numeric(18,2) not null default 0 check (freight_per_bag >= 0),\n  loading_charges  numeric(18,2) not null default 0 check (loading_charges >= 0),\n  goods_value      numeric(18,2) not null default 0,\n  freight_value    numeric(18,2) not null default 0,   -- freight charged to the customer\n  discount_value   numeric(18,2) not null default 0,   -- share of the OG discount\n  journal_entry_id bigint references journal_entries(id),\n  created_by       int not null references users(id),\n  created_at       timestamptz not null default now()\n);\n\ncreate table dispatch_lines (\n  id            bigserial primary key,\n  dispatch_id   bigint not null references dispatches(id),\n  og_line_id    bigint not null references og_lines(id),\n  product_id    int not null references products(id),\n  bags          int not null check (bags > 0)\n);\ncreate trigger dispatch_lines_no_change before update or delete on dispatch_lines\n  for each row execute function forbid_change();\ncreate trigger dispatches_no_change before update or delete on dispatches\n  for each row execute function forbid_change();\n\n-- ---------------------------------------------------------------------------\ncreate table receipts (\n  id               bigserial primary key,\n  receipt_no       text not null unique,\n  business_date    date not null,\n  party_id         int not null references parties(id),\n  mode             text not null check (mode in ('cash','bank_transfer','cheque','online')),\n  account_id       int not null references accounts(id),   -- cash or bank ledger account\n  instrument_no    text,\n  drawer_bank      text,\n  amount           numeric(18,2) not null check (amount > 0),\n  status           text not null default 'posted' check (status in ('posted','returned')),\n  journal_entry_id bigint not null references journal_entries(id),\n  note             text,\n  created_by       int not null references users(id),\n  created_at       timestamptz not null default now(),\n  rep_user_id      int references users(id),\n  check (mode = 'cash' or instrument_no is not null)\n);\ncreate unique index receipts_cheque_unique on receipts (lower(coalesce(drawer_bank,'')), instrument_no)\n  where mode = 'cheque';\n\ncreate table receipt_allocations (\n  id            bigserial primary key,\n  receipt_id    bigint not null references receipts(id),\n  og_id         bigint not null references ogs(id),\n  amount        numeric(18,2) not null check (amount > 0),\n  created_by    int not null references users(id),\n  created_at    timestamptz not null default now(),\n  reversed_at   timestamptz,\n  reversed_by_return_id bigint\n);\ncreate index ra_og_idx on receipt_allocations(og_id);\n\ncreate table cheque_returns (\n  id               bigserial primary key,\n  return_no        text not null unique,\n  receipt_id       bigint not null unique references receipts(id),\n  business_date    date not null,\n  reason           text not null,\n  bank_charges     numeric(18,2) not null default 0 check (bank_charges >= 0),\n  journal_entry_id bigint not null references journal_entries(id),\n  created_by       int not null references users(id),\n  created_at       timestamptz not null default now()\n);\n\n-- ---------------------------------------------------------------------------\n-- Derived OG figures. Value = goods + freight charged to customer − discount.\ncreate view og_totals as\n  select o.id as og_id,\n         coalesce(sum(l.bags),0)::bigint as bags,\n         coalesce(sum(l.bags * l.rate),0) as goods_value,\n         case when o.freight_by = 'customer' then coalesce(sum(l.bags),0) * o.freight_per_bag else 0 end as freight_value,\n         coalesce(sum(l.bags * l.rate),0)\n           + case when o.freight_by = 'customer' then coalesce(sum(l.bags),0) * o.freight_per_bag else 0 end\n           - o.discount as total_value\n    from ogs o left join og_lines l on l.og_id = o.id\n   group by o.id;\n\ncreate view og_dispatched as\n  select o.id as og_id, coalesce(sum(dl.bags),0)::bigint as bags\n    from ogs o\n    left join og_lines ol on ol.og_id = o.id\n    left join dispatch_lines dl on dl.og_line_id = ol.id\n   group by o.id;\n\ncreate view og_line_dispatched as\n  select ol.id as og_line_id, ol.og_id, ol.bags, coalesce(sum(dl.bags),0)::bigint as dispatched\n    from og_lines ol left join dispatch_lines dl on dl.og_line_id = ol.id\n   group by ol.id;\n\ncreate view og_paid as\n  select o.id as og_id, coalesce(sum(a.amount) filter (where a.reversed_at is null),0) as paid\n    from ogs o left join receipt_allocations a on a.og_id = o.id\n   group by o.id;\n\ncreate view og_status as\n  select o.id as og_id,\n         t.bags, t.total_value, d.bags as dispatched_bags, p.paid,\n         t.total_value - p.paid as outstanding,\n         case\n           when o.status in ('draft','submitted','rejected','cancelled') then initcap(o.status)\n           when d.bags = 0 then 'Approved'\n           when d.bags < t.bags then 'Partly dispatched'\n           else 'Dispatched'\n         end as fulfilment,\n         case\n           when p.paid >= t.total_value and t.total_value > 0 then 'Paid'\n           when o.due_date is not null and o.due_date < current_date and o.status = 'approved' then 'Overdue'\n           when p.paid > 0 then 'Partly paid'\n           else 'Unpaid'\n         end as payment\n    from ogs o\n    join og_totals t on t.og_id = o.id\n    join og_dispatched d on d.og_id = o.id\n    join og_paid p on p.og_id = o.id;\n\n-- Committed stock: approved OG bags not yet dispatched, per product and branch.\ncreate view stock_committed as\n  select o.branch_id, ld.og_line_id, l.product_id, (ld.bags - ld.dispatched)::bigint as bags\n    from og_line_dispatched ld\n    join og_lines l on l.id = ld.og_line_id\n    join ogs o on o.id = ld.og_id\n   where o.status = 'approved' and ld.bags > ld.dispatched;\n"],
  ["006_security.sql", "-- 006_security: change guards on business records, row-level security, and grants for akb_app.\n\n-- ---------------------------------------------------------------------------\n-- Guards: which columns may change after a record is created.\n-- ---------------------------------------------------------------------------\ncreate or replace function only_columns_change(old_row jsonb, new_row jsonb, allowed text[]) returns boolean\nlanguage sql immutable as $$\n  select (old_row - allowed) = (new_row - allowed)\n$$;\n\ncreate or replace function ogs_guard() returns trigger language plpgsql as $$\nbegin\n  if tg_op = 'DELETE' then\n    if old.status <> 'draft' then\n      raise exception 'Only draft OGs can be deleted; cancel it instead' using errcode = 'P0001';\n    end if;\n    return old;\n  end if;\n  if old.status <> 'draft' and not only_columns_change(to_jsonb(old), to_jsonb(new),\n       array['status','decided_by','decided_at','decision_comment','due_date']) then\n    raise exception 'OG % can no longer be edited', old.og_no using errcode = 'P0001';\n  end if;\n  if old.status in ('rejected','cancelled') and new.status <> old.status then\n    raise exception 'OG % is closed', old.og_no using errcode = 'P0001';\n  end if;\n  return new;\nend $$;\ncreate trigger ogs_guard before update or delete on ogs\n  for each row execute function ogs_guard();\n\ncreate or replace function receipts_guard() returns trigger language plpgsql as $$\nbegin\n  if tg_op = 'UPDATE' and old.status = 'posted' and new.status = 'returned'\n     and only_columns_change(to_jsonb(old), to_jsonb(new), array['status']) then\n    return new;\n  end if;\n  raise exception 'Posted receipts cannot be changed; record a cheque return or reversal' using errcode = 'P0001';\nend $$;\ncreate trigger receipts_guard before update or delete on receipts\n  for each row execute function receipts_guard();\n\ncreate or replace function allocations_guard() returns trigger language plpgsql as $$\nbegin\n  if tg_op = 'UPDATE' and old.reversed_at is null and new.reversed_at is not null\n     and only_columns_change(to_jsonb(old), to_jsonb(new), array['reversed_at','reversed_by_return_id']) then\n    return new;\n  end if;\n  raise exception 'Receipt allocations cannot be changed' using errcode = 'P0001';\nend $$;\ncreate trigger allocations_guard before update or delete on receipt_allocations\n  for each row execute function allocations_guard();\n\ncreate trigger cheque_returns_no_change before update or delete on cheque_returns\n  for each row execute function forbid_change();\ncreate trigger goods_receipts_no_change before update or delete on goods_receipts\n  for each row execute function forbid_change();\ncreate trigger goods_receipt_lines_no_change before update or delete on goods_receipt_lines\n  for each row execute function forbid_change();\ncreate trigger stock_transfer_lines_no_change before update or delete on stock_transfer_lines\n  for each row execute function forbid_change();\n\ncreate or replace function transfers_guard() returns trigger language plpgsql as $$\nbegin\n  if tg_op = 'UPDATE' and old.status = 'in_transit' and new.status = 'received'\n     and only_columns_change(to_jsonb(old), to_jsonb(new), array['status','received_by','received_at','received_date']) then\n    return new;\n  end if;\n  raise exception 'Stock transfers cannot be changed after sending' using errcode = 'P0001';\nend $$;\ncreate trigger transfers_guard before update or delete on stock_transfers\n  for each row execute function transfers_guard();\n\ncreate or replace function adjustments_guard() returns trigger language plpgsql as $$\nbegin\n  if tg_op = 'UPDATE' and old.status = 'pending' and new.status in ('approved','rejected')\n     and only_columns_change(to_jsonb(old), to_jsonb(new), array['status','decided_by','decided_at','decision_note']) then\n    if new.decided_by = old.requested_by then\n      raise exception 'The person who requested an adjustment cannot approve it' using errcode = 'P0001';\n    end if;\n    return new;\n  end if;\n  raise exception 'Stock adjustments cannot be changed after a decision' using errcode = 'P0001';\nend $$;\ncreate trigger adjustments_guard before update or delete on stock_adjustments\n  for each row execute function adjustments_guard();\n\ncreate or replace function day_lock_guard() returns trigger language plpgsql as $$\nbegin\n  if tg_op = 'DELETE' or (old.status = 'locked') then\n    raise exception 'A locked business day cannot be reopened or changed' using errcode = 'P0001';\n  end if;\n  return new;\nend $$;\ncreate trigger day_lock_guard before update or delete on business_days\n  for each row execute function day_lock_guard();\n\n-- ---------------------------------------------------------------------------\n-- Row-level security. Fails closed: with no app.role set, akb_app sees nothing.\n-- Sales reps see only the customers, OGs and receipts assigned to them.\n-- ---------------------------------------------------------------------------\nalter table parties  enable row level security;\nalter table ogs      enable row level security;\nalter table receipts enable row level security;\n\ncreate policy parties_scope on parties\n  using (app_role() is not null and (app_role() <> 'sales' or kind <> 'customer' or rep_user_id = app_user_id()))\n  with check (app_role() is not null and (app_role() <> 'sales' or kind <> 'customer' or rep_user_id = app_user_id()));\n\ncreate policy ogs_scope on ogs\n  using (app_role() is not null and (app_role() <> 'sales' or rep_user_id = app_user_id()))\n  with check (app_role() is not null and (app_role() <> 'sales' or rep_user_id = app_user_id()));\n\ncreate policy receipts_scope on receipts\n  using (app_role() is not null and (app_role() <> 'sales' or rep_user_id = app_user_id()))\n  with check (app_role() is not null and (app_role() <> 'sales' or rep_user_id = app_user_id()));\n\n-- ---------------------------------------------------------------------------\n-- Grants. akb_app can read everything and insert records; it can update only\n-- where a workflow needs it (the guards above limit what), and delete only drafts.\n-- It owns no tables, so it cannot drop or alter anything.\n-- ---------------------------------------------------------------------------\ngrant usage on schema public to akb_app;\ngrant select, insert on all tables in schema public to akb_app;\ngrant usage, select on all sequences in schema public to akb_app;\n\ngrant update on users, sessions, parties, products, accounts, bank_accounts, business_days,\n  journal_entries, journal_lines, doc_counters, ogs, og_lines, receipts, receipt_allocations,\n  stock_transfers, stock_adjustments, branches, idempotency_keys to akb_app;\ngrant delete on journal_entries, journal_lines, ogs, og_lines, sessions, idempotency_keys to akb_app;\n\nrevoke update, delete on audit_log, stock_movements, dispatches, dispatch_lines, cheque_returns,\n  goods_receipts, goods_receipt_lines, stock_transfer_lines from akb_app;\n"],
  ["007_approvals.sql", "-- 007_approvals: reversal requests (maker-checker for corrections).\n\ncreate table reversal_requests (\n  id              bigserial primary key,\n  entry_id        bigint not null references journal_entries(id),\n  reason          text not null,\n  requested_by    int not null references users(id),\n  requested_at    timestamptz not null default now(),\n  status          text not null default 'pending' check (status in ('pending','approved','rejected')),\n  decided_by      int references users(id),\n  decided_at      timestamptz,\n  decision_note   text,\n  reversal_entry_id bigint references journal_entries(id)\n);\ncreate unique index reversal_requests_one_pending on reversal_requests(entry_id) where status = 'pending';\n\ncreate or replace function reversal_requests_guard() returns trigger language plpgsql as $$\nbegin\n  if tg_op = 'UPDATE' and old.status = 'pending' and new.status in ('approved','rejected')\n     and only_columns_change(to_jsonb(old), to_jsonb(new), array['status','decided_by','decided_at','decision_note','reversal_entry_id']) then\n    if new.decided_by = old.requested_by then\n      raise exception 'The person who requested a reversal cannot approve it' using errcode = 'P0001';\n    end if;\n    return new;\n  end if;\n  raise exception 'Reversal requests cannot be changed after a decision' using errcode = 'P0001';\nend $$;\ncreate trigger reversal_requests_guard before update or delete on reversal_requests\n  for each row execute function reversal_requests_guard();\n\ngrant select, insert, update on reversal_requests to akb_app;\ngrant usage, select on sequence reversal_requests_id_seq to akb_app;\n"],
  ["008_reference.sql", "-- 008_reference: reference data every installation needs: roles, permissions, cost centres,\n-- and a starting chart of accounts (finance can extend it; codes are stable).\n\ninsert into roles(code, name, description) values\n  ('owner',        'Owner / Director', 'Sees everything; approves overrides'),\n  ('finance',      'Finance',          'Bank facilities, guarantees, financing'),\n  ('procurement',  'Procurement',      'Suppliers and company orders'),\n  ('sales',        'Sales rep',        'Own customers and OGs only'),\n  ('distribution', 'Distribution',     'Goods receipt, dispatch, transfers; no prices'),\n  ('accounts',     'Accounts',         'Receipts, payments, ledgers, day close'),\n  ('auditor',      'Auditor',          'Read-only'),\n  ('admin',        'Admin',            'Users and settings; no financial entries');\n\ninsert into permissions(code, description) values\n  ('dashboard.read',      'View the owner dashboard'),\n  ('money.read',          'See prices, amounts and balances'),\n  ('masters.read',        'View parties, products, branches, accounts'),\n  ('masters.write',       'Create and edit parties, products, branches, accounts'),\n  ('ledger.read',         'View journals, ledgers and trial balance'),\n  ('journal.create',      'Create manual journal entries'),\n  ('journal.approve',     'Approve manual journal entries'),\n  ('reversal.request',    'Request a reversal'),\n  ('reversal.approve',    'Approve a reversal'),\n  ('og.read',             'View all OGs'),\n  ('og.read.own',         'View own customers'' OGs'),\n  ('og.create',           'Create and submit OGs'),\n  ('og.approve',          'Approve or reject OGs'),\n  ('og.cancel',           'Cancel OGs'),\n  ('dispatch.create',     'Dispatch goods against OGs'),\n  ('stock.read',          'View stock'),\n  ('stock.receive',       'Record goods received'),\n  ('stock.transfer',      'Send and receive stock transfers'),\n  ('stock.adjust.request','Request stock adjustments'),\n  ('stock.adjust.approve','Approve stock adjustments'),\n  ('receipt.read',        'View receipts'),\n  ('receipt.create',      'Record receipts and allocate them'),\n  ('cheque.return',       'Record returned cheques'),\n  ('day.close',           'Close and lock a business day'),\n  ('daybook.export',      'Download the day book'),\n  ('users.manage',        'Create users, set roles, reset access'),\n  ('audit.read',          'View the audit log');\n\ninsert into role_permissions(role_code, permission_code)\n  select 'owner', code from permissions;\n\ninsert into role_permissions(role_code, permission_code)\n  select r, p from (values\n    ('accounts','dashboard.read'),('accounts','money.read'),('accounts','masters.read'),('accounts','masters.write'),\n    ('accounts','ledger.read'),('accounts','journal.create'),('accounts','reversal.request'),('accounts','og.read'),\n    ('accounts','receipt.read'),('accounts','receipt.create'),('accounts','cheque.return'),('accounts','day.close'),\n    ('accounts','daybook.export'),('accounts','stock.read'),\n    ('sales','money.read'),('sales','masters.read'),('sales','og.read.own'),('sales','og.create'),\n    ('sales','stock.read'),('sales','receipt.read'),\n    ('distribution','masters.read'),('distribution','og.read'),('distribution','dispatch.create'),\n    ('distribution','stock.read'),('distribution','stock.receive'),('distribution','stock.transfer'),\n    ('distribution','stock.adjust.request'),\n    ('procurement','money.read'),('procurement','masters.read'),('procurement','masters.write'),\n    ('procurement','stock.read'),('procurement','stock.receive'),\n    ('finance','dashboard.read'),('finance','money.read'),('finance','masters.read'),('finance','ledger.read'),\n    ('finance','journal.create'),('finance','reversal.request'),('finance','stock.read'),('finance','receipt.read'),\n    ('auditor','dashboard.read'),('auditor','money.read'),('auditor','masters.read'),('auditor','ledger.read'),\n    ('auditor','og.read'),('auditor','receipt.read'),('auditor','stock.read'),('auditor','audit.read'),\n    ('auditor','daybook.export'),\n    ('admin','masters.read'),('admin','masters.write'),('admin','users.manage'),('admin','audit.read')\n  ) as t(r, p);\n\ninsert into cost_centres(code, name) values\n  ('BUSINESS', 'Fertilizer business'),\n  ('RENTAL',   'Rental'),\n  ('PERSONAL', 'Owners'' personal');\n\n-- Chart of accounts. Headers are not postable; leaves are.\ninsert into accounts(code, name, type, postable) values\n  ('1000','Assets','asset',false),\n  ('2000','Liabilities','liability',false),\n  ('3000','Equity','equity',false),\n  ('4000','Income','income',false),\n  ('5000','Expenses','expense',false);\n\ninsert into accounts(code, name, type, parent_id, postable, control)\nselect v.code, v.name, v.type, (select id from accounts where code = v.parent), v.postable, v.control\nfrom (values\n  ('1100','Cash in hand','asset','1000',false,null),\n  ('1101','Main cash','asset','1100',true,'cash'),\n  ('1200','Bank accounts','asset','1000',false,null),\n  ('1300','Trade receivables','asset','1000',true,'receivable'),\n  ('1400','Stock in trade','asset','1000',true,null),\n  ('1500','Advances to suppliers','asset','1000',true,'payable'),\n  ('1600','Margin money with banks','asset','1000',true,null),\n  ('1700','Claims receivable from companies','asset','1000',true,null),\n  ('1800','Cheques in hand','asset','1000',true,null),\n  ('2100','Trade payables','liability','2000',true,'payable'),\n  ('2200','Bank borrowings','liability','2000',false,null),\n  ('2300','Taxes payable','liability','2000',true,null),\n  ('2400','Accrued expenses','liability','2000',true,null),\n  ('3100','Owners'' capital','equity','3000',true,null),\n  ('3200','Owners'' drawings','equity','3000',true,null),\n  ('3300','Opening balance equity','equity','3000',true,null),\n  ('4100','Sales','income','4000',true,null),\n  ('4200','Freight recovered','income','4000',true,null),\n  ('4300','Rental income','income','4000',true,null),\n  ('4900','Other income','income','4000',true,null),\n  ('5100','Cost of sales','expense','5000',true,null),\n  ('5200','Freight and loading','expense','5000',true,null),\n  ('5300','Bank charges and markup','expense','5000',true,null),\n  ('5400','Salaries and wages','expense','5000',true,null),\n  ('5500','Office and utilities','expense','5000',true,null),\n  ('5600','Discounts allowed','expense','5000',true,null),\n  ('5900','Other expenses','expense','5000',true,null),\n  ('9999','Cash book import suspense','asset',null,true,null)\n) as v(code, name, type, parent, postable, control);\n"],
  ["009_login_throttle.sql", "-- 009_login_throttle: sign-in attempts per address, kept in the database so the limit holds\n-- when the API runs as several short-lived copies (Vercel). Rows older than an hour are pruned.\ncreate table login_attempts (\n  id  bigserial primary key,\n  ip  text not null,\n  at  timestamptz not null default now()\n);\ncreate index login_attempts_ip_at on login_attempts(ip, at);\n\ngrant select, insert, delete on login_attempts to akb_app;\ngrant usage, select on sequence login_attempts_id_seq to akb_app;\n"]
];
